#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/ztest.h>
#include <zephyr/devicetree.h>

/*
 * Get the GPIO device from DT_ALIAS(gpio0).
 * This assumes that the board's devicetree or an app.overlay
 * defines an alias 'gpio0' pointing to a suitable GPIO controller.
 * It also assumes that the 'gpio0' node has a 'test_pin' property
 * defined for the purpose of this test.
 */
#if DT_NODE_HAS_STATUS(DT_ALIAS(gpio0), okay)
#define GPIO_DEV_NODE DT_ALIAS(gpio0)
#define GPIO_TEST_PIN DT_GPIO_PIN(DT_ALIAS(gpio0), test_pin)
#define GPIO_TEST_FLAGS DT_GPIO_FLAGS(DT_ALIAS(gpio0), test_pin)
#else
#error "GPIO device alias 'gpio0' or its 'test_pin' property not defined or enabled in devicetree."
#endif

static const struct device *gpio_dev;
static const struct gpio_dt_spec gpio_pin = {
    .port = DEVICE_DT_GET(GPIO_DEV_NODE),
    .pin = GPIO_TEST_PIN,
    .dt_flags = GPIO_TEST_FLAGS,
};

static void *gpio_get_direction_setup(void)
{
    gpio_dev = gpio_pin.port;
    zassert_true(device_is_ready(gpio_dev), "GPIO device is not ready");

    /* Ensure the pin is configured as output initially for testing direction changes */
    int ret = gpio_pin_configure_dt(&gpio_pin, GPIO_OUTPUT);
    zassert_equal(ret, 0, "Failed to configure GPIO pin as output");

    return NULL;
}

ZTEST_SUITE(gpio_get_direction, NULL, gpio_get_direction_setup, NULL, NULL, NULL);

/* Test case 1: Check initial direction (output) */
ZTEST(gpio_get_direction, test_gpio_get_direction_output)
{
    enum gpio_direction dir;
    int ret = gpio_get_direction(gpio_dev, gpio_pin.pin, &dir);
    zassert_equal(ret, 0, "Failed to get GPIO direction");
    zassert_equal(dir, GPIO_DIRECTION_OUT, "Expected output direction");
}

/* Test case 2: Change to input and check direction */
ZTEST(gpio_get_direction, test_gpio_get_direction_input)
{
    int ret = gpio_pin_configure_dt(&gpio_pin, GPIO_INPUT);
    zassert_equal(ret, 0, "Failed to configure GPIO pin as input");

    enum gpio_direction dir;
    ret = gpio_get_direction(gpio_dev, gpio_pin.pin, &dir);
    zassert_equal(ret, 0, "Failed to get GPIO direction");
    zassert_equal(dir, GPIO_DIRECTION_IN, "Expected input direction");
}

/* Test case 3: Change to output and check direction again */
ZTEST(gpio_get_direction, test_gpio_get_direction_output_again)
{
    int ret = gpio_pin_configure_dt(&gpio_pin, GPIO_OUTPUT);
    zassert_equal(ret, 0, "Failed to configure GPIO pin as output");

    enum gpio_direction dir;
    ret = gpio_get_direction(gpio_dev, gpio_pin.pin, &dir);
    zassert_equal(ret, 0, "Failed to get GPIO direction");
    zassert_equal(dir, GPIO_DIRECTION_OUT, "Expected output direction");
}

/* Test case 4: Check with invalid pin (should return error) */
ZTEST(gpio_get_direction, test_gpio_get_direction_invalid_pin)
{
    enum gpio_direction dir;
    int ret = gpio_get_direction(gpio_dev, 999, &dir); // Assuming 999 is an invalid pin
    zassert_not_equal(ret, 0, "Expected error for invalid pin");
}
